predicted_sql:
SELECT
  (SELECT COUNT(*) FROM gasstations WHERE Segment = 'Discount' AND Country = 'CZE')
  - (SELECT COUNT(*) FROM gasstations WHERE Segment = 'Discount' AND Country = 'SVK');

SELECT (COALESCE(SUM(CASE WHEN Currency='CZK' THEN 1 ELSE 0 END),0) - COALESCE(SUM(CASE WHEN Currency='EUR' THEN 1 ELSE 0 END),0)) AS difference
FROM customers
WHERE Segment = 'SME' AND Currency IS NOT NULL;

SELECT 100.0 * SUM(CASE WHEN Segment = 'Premium' THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM gasstations
WHERE Country = 'SVK';

SELECT ROUND(100.0 * SUM(CASE WHEN SEX = 'F' AND Birthday > '1930-12-31' THEN 1 ELSE 0 END) / COUNT(*), 2) AS percentage
FROM Patient
WHERE SEX IS NOT NULL AND SEX != '' AND Birthday IS NOT NULL AND Birthday != '';

SELECT ABS(
  (SELECT AVG(PA.ball_control) FROM Player_Attributes PA JOIN Player P ON P.player_api_id = PA.player_api_id WHERE P.player_name = 'Abdou Diallo' AND PA.ball_control IS NOT NULL)
  -
  (SELECT AVG(PA2.ball_control) FROM Player_Attributes PA2 JOIN Player P2 ON P2.player_api_id = PA2.player_api_id WHERE P2.player_name = 'Aaron Appindangoye' AND PA2.ball_control IS NOT NULL)
) AS difference;

SELECT League.name
FROM Match
JOIN League ON Match.league_id = League.id
WHERE Match.season = '2008/2009'
GROUP BY League.name
HAVING COUNT(*) = (
  SELECT MAX(cnt) FROM (
    SELECT COUNT(*) AS cnt FROM Match WHERE season = '2008/2009' GROUP BY league_id
  )
);

SELECT ABS(
  (SELECT jumping FROM Player_Attributes WHERE player_api_id = 6  AND date = (SELECT MAX(date) FROM Player_Attributes WHERE player_api_id = 6))
  -
  (SELECT jumping FROM Player_Attributes WHERE player_api_id = 23 AND date = (SELECT MAX(date) FROM Player_Attributes WHERE player_api_id = 23))
) AS difference;

SELECT location, lat, lng
FROM circuits
WHERE country = 'Malaysia' OR circuitRef = 'sepang';

SELECT ABS(
  (SELECT COUNT(*) FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE p.publisher_name = 'Marvel Comics')
  -
  (SELECT COUNT(*) FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE p.publisher_name = 'DC Comics')
) AS difference;

SELECT DISTINCT id FROM (
  SELECT id FROM publisher WHERE publisher_name = 'Star Trek'
  UNION
  SELECT publisher_id AS id FROM superhero WHERE superhero_name = 'Star Trek' AND publisher_id IS NOT NULL
);

SELECT
  ( (SELECT weight_kg FROM superhero WHERE full_name = 'Emil Blonsky' OR superhero_name = 'Emil Blonsky')
  -
    (SELECT weight_kg FROM superhero WHERE full_name = 'Charles Chandler' OR superhero_name = 'Charles Chandler')
  );

SELECT (SUM(CASE WHEN lower(colour.colour) = 'blue' THEN 1 ELSE 0 END) * 100.0) / COUNT(*) AS percentage
FROM superhero
LEFT JOIN colour ON superhero.eye_colour_id = colour.id;

SELECT ABS(
  (SELECT COUNT(*) FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE p.publisher_name = 'DC Comics' AND p.publisher_name IS NOT NULL)
  -
  (SELECT COUNT(*) FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE p.publisher_name = 'Marvel Comics' AND p.publisher_name IS NOT NULL)
) AS difference;

SELECT CASE WHEN total = 0 THEN NULL ELSE 100.0 * above / total END AS percentage
FROM (
  SELECT COUNT(*) AS total,
         SUM(CASE WHEN Score > 50 THEN 1 ELSE 0 END) AS above
  FROM posts
  WHERE OwnerUserId IN (
    SELECT Id FROM users WHERE Reputation = (SELECT MAX(Reputation) FROM users)
  )
);

SELECT ExcerptPostId, WikiPostId
FROM tags
WHERE TagName = 'sample';

SELECT CASE WHEN total = 0 THEN 0.0 ELSE (100.0 * french_count / total) END AS percentage
FROM (
  SELECT
    (SELECT COUNT(DISTINCT uuid) FROM cards WHERE isStorySpotlight = 1) AS total,
    (SELECT COUNT(DISTINCT c.uuid) FROM cards c JOIN foreign_data f ON c.uuid = f.uuid WHERE c.isStorySpotlight = 1 AND f.language = 'French') AS french_count
);

SELECT CASE WHEN denom.cnt = 0 THEN 0.0 ELSE (num.cnt * 100.0) / denom.cnt END
FROM (SELECT COUNT(DISTINCT uuid) AS cnt FROM cards WHERE power IS NULL) denom,
     (SELECT COUNT(DISTINCT cards.uuid) AS cnt FROM cards JOIN foreign_data ON cards.uuid = foreign_data.uuid WHERE cards.power IS NULL AND foreign_data.language = 'French') num;

SELECT (SUM(CASE WHEN element = 'c' THEN 1 ELSE 0 END) * 100.0) / COUNT(*) AS percentage
FROM atom
WHERE molecule_id IN (SELECT molecule_id FROM bond WHERE bond_type = '=');

SELECT CASE WHEN total = 0 THEN NULL ELSE (no_f * 100.0) / total END AS percentage
FROM (
  SELECT
    (SELECT COUNT(DISTINCT molecule_id) FROM molecule WHERE label = '+') AS total,
    (SELECT COUNT(DISTINCT m.molecule_id) FROM molecule m
     WHERE m.label = '+'
       AND NOT EXISTS (SELECT 1 FROM atom a WHERE a.molecule_id = m.molecule_id AND a.element = 'f')
    ) AS no_f
);

SELECT COUNT(DISTINCT a.atom_id)
FROM atom a
WHERE EXISTS (
  SELECT 1 FROM bond b
  WHERE b.molecule_id = a.molecule_id AND b.bond_type = '#'
)
AND EXISTS (
  SELECT 1 FROM atom a2
  WHERE a2.molecule_id = a.molecule_id AND a2.element IN ('p','br')
);
